    close: () =>
      new Promise<void>((closed, reject) => {
        server.close((error) => {
          if (error) reject(error);
          else closed();
        });
      }),
  };
}

export const REFERENCE_ROOT = fileURLToPath(new URL('../', import.meta.url));

